-- Visitor-only signup; privileged identities must be provisioned by an operator.
alter table public.codeverse_profiles drop constraint if exists codeverse_profiles_role_check;
alter table public.codeverse_profiles add constraint codeverse_profiles_role_check check(role in ('visitor','developer','recruiter','security_admin'));
alter table public.codeverse_security_events drop constraint if exists codeverse_security_events_role_check;
alter table public.codeverse_security_events add constraint codeverse_security_events_role_check check(role in ('anonymous','visitor','developer','recruiter','security_admin'));
create or replace function public.codeverse_on_auth_signup() returns trigger language plpgsql security definer set search_path = '' as $$
begin
 values(new.id,coalesce(new.email,''),'visitor',left(coalesce(new.raw_user_meta_data->>'name',''),120),left(coalesce(new.raw_user_meta_data->>'user_name',''),39)) on conflict(id) do nothing;
 return new;
end;$$;
create table if not exists public.codeverse_workspace_state (
 user_id uuid primary key references auth.users(id) on delete cascade,
 payload jsonb not null default '{}'::jsonb, revision integer not null default 1, updated_at timestamptz not null default now()
);
create table if not exists public.codeverse_private_integrations (
 user_id uuid not null references auth.users(id) on delete cascade, provider text not null,
 encrypted text not null, primary key(user_id,provider)
);
create table if not exists public.codeverse_repo_catalog(id text primary key, data jsonb not null);
alter table public.codeverse_workspace_state enable row level security;
alter table public.codeverse_private_integrations enable row level security;
alter table public.codeverse_repo_catalog enable row level security;
revoke all on public.codeverse_workspace_state,public.codeverse_private_integrations from anon,authenticated;
grant all on public.codeverse_workspace_state,public.codeverse_private_integrations to service_role;
grant select on public.codeverse_repo_catalog to anon,authenticated;
create policy "public reference catalog" on public.codeverse_repo_catalog for select using(true);
